    public function useFacturaQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinFactura($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'Factura', 'FacturaQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   FacturaAuditImage $facturaAuditImage Object to remove from the list of results
     *
     * @return FacturaAuditImageQuery The current query, for fluid interface
     */
    public function prune($facturaAuditImage = null)
    {
        if ($facturaAuditImage) {
            $this->addUsingAlias(FacturaAuditImagePeer::FACTURAAUDITIMAGE_ID, $facturaAuditImage->getFacturaauditimageId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

}
